-- MathLabs v28.0 → v28.4 · 7B REVIEWED RC2 COMPAT3 · LEGACY-PRESERVING STAGING INSTALL
-- 19 OA · 38 topics · 152 nodes · deep content · 988 assessment items · adaptive · diagnostic · routes.
-- RC2: contract-audited content. No publication controller. No live student delivery.
begin;
select public.mathlabs_assert_admin_v22();

do $$
begin
 if (select count(*) from public.courses where id='cl-7-basico')<>1 then raise exception 'Preflight v28.0: cl-7-basico no existe en public.courses'; end if;
 if to_regclass('public.mathlabs_course_catalog_v259') is null
    or to_regclass('public.multigrade_assessment_items_v261') is null
    or to_regclass('public.multigrade_adaptive_item_metadata_v262') is null
    or to_regclass('public.multigrade_diagnostic_blueprints_v263') is null
    or to_regclass('public.multigrade_learning_route_contract_v264') is null
    or to_regclass('public.multigrade_assessment_certification_v264') is null
    or to_regclass('public.multigrade_assessment_readiness_v264') is null
    or to_regclass('public.multigrade_curriculum_source_snapshot_v269') is null
    or to_regclass('public.multigrade_course_runtime_gate_v269') is null then
   raise exception 'Falta arquitectura V25.9-V27.9 requerida por 7B';
 end if;
 if (select count(*) from public.mathlabs_course_catalog_v259 where course_id='cl-7-basico')<>1 then
   raise exception 'cl-7-basico no está registrado en V25.9';
 end if;
 if (select count(*) from public.curriculum_axes where course_id='cl-7-basico')<>4
    or (select count(*) from public.curriculum_axes where course_id='cl-7-basico' and is_published)<>4
    or exists(select 1 from public.curriculum_axes where course_id='cl-7-basico' and id like 'axis-v280-7b-%')
    or (select count(*) from public.curriculum_objectives where course_id='cl-7-basico')<>19
    or (select count(*) from public.curriculum_objectives where course_id='cl-7-basico' and is_published)<>19
    or exists(select 1 from public.curriculum_objectives where course_id='cl-7-basico' and id like 'obj-v280-ma07-%')
    or (select array_agg(code order by code) from public.curriculum_objectives where course_id='cl-7-basico')
       <> array['MA07 OA 01','MA07 OA 02','MA07 OA 03','MA07 OA 04','MA07 OA 05','MA07 OA 06','MA07 OA 07','MA07 OA 08','MA07 OA 09','MA07 OA 10','MA07 OA 11','MA07 OA 12','MA07 OA 13','MA07 OA 14','MA07 OA 15','MA07 OA 16','MA07 OA 17','MA07 OA 18','MA07 OA 19']::text[]
    or (select count(*) from public.knowledge_topics where course_id='cl-7-basico')<>35
    or (select count(*) from public.knowledge_topics where course_id='cl-7-basico' and is_published)<>35
    or exists(select 1 from public.knowledge_topics where course_id='cl-7-basico'
              and (id like 'topic-v280-ma07-%' or slug like 'v280-7b-%'))
    or (select count(*) from public.curriculum_objective_topics link
        join public.curriculum_objectives objective on objective.id=link.objective_id
        where objective.course_id='cl-7-basico')<>35 then
   raise exception 'Compat3: baseline legado publicado de cl-7-basico no coincide con 4/19/35/35';
 end if;

 if exists(select 1 from public.curriculum_sources_v254 where course_id='cl-7-basico')
 or exists(select 1 from public.curriculum_oas_v254 where course_id='cl-7-basico')
 or exists(select 1 from public.deep_learning_paths_v250 where course_id='cl-7-basico')
 or exists(select 1 from public.curriculum_nodes_v254 where course_id='cl-7-basico')
 or exists(select 1 from public.curriculum_coverage_v254 where course_id='cl-7-basico')
 or exists(select 1 from public.curriculum_topic_readiness_v254 where course_id='cl-7-basico')
 or exists(select 1 from public.multigrade_assessment_items_v261 where course_id='cl-7-basico')
 or exists(select 1 from public.multigrade_review_sets_v261 where course_id='cl-7-basico')
 or exists(select 1 from public.multigrade_adaptive_item_metadata_v262 where course_id='cl-7-basico')
 or exists(select 1 from public.multigrade_diagnostic_blueprints_v263 where course_id='cl-7-basico')
 or exists(select 1 from public.multigrade_learning_route_contract_v264 where course_id='cl-7-basico')
 or exists(select 1 from public.multigrade_assessment_certification_v264 where course_id='cl-7-basico')
 or exists(select 1 from public.multigrade_assessment_readiness_v264 where course_id='cl-7-basico')
 or exists(select 1 from public.multigrade_curriculum_source_snapshot_v269 where course_id='cl-7-basico')
 or exists(select 1 from public.multigrade_course_runtime_gate_v269 where course_id='cl-7-basico') then
   raise exception 'Compat3: namespace multigrado V28.0 de cl-7-basico no está limpio';
 end if;

 if (select count(*) from public.mathlabs_course_catalog_v259
     where course_id='cl-7-basico' and lifecycle_status='planned' and content_version is null)<>1 then
   raise exception 'Compat3: catálogo legado de cl-7-basico no está en planned sin versión';
 end if;

 if (select count(*)
     from pg_constraint c
     where c.conrelid='public.knowledge_topics'::regclass
       and c.conname='knowledge_topics_difficulty_check'
       and position('''Inicial''' in pg_get_constraintdef(c.oid))>0
       and position('''Fundamental''' in pg_get_constraintdef(c.oid))>0
       and position('''Intermedio''' in pg_get_constraintdef(c.oid))>0
       and position('''Avanzado''' in pg_get_constraintdef(c.oid))>0)<>1 then
   raise exception 'Compat3: knowledge_topics_difficulty_check no admite Inicial/Fundamental/Intermedio/Avanzado';
 end if;

 if (select count(*) from pg_constraint c
     where c.conrelid='public.deep_guided_answer_keys_v253'::regclass
       and c.conname='deep_guided_answer_keys_v253_validation_type_check'
       and position('''numeric''' in pg_get_constraintdef(c.oid))>0
       and position('''mixed''' in pg_get_constraintdef(c.oid))>0
       and position('''formula''' in pg_get_constraintdef(c.oid))>0
       and position('''keywords''' in pg_get_constraintdef(c.oid))>0)<>1 then
   raise exception 'Compat3: contrato validation_type de deep_guided_answer_keys_v253 incompatible';
 end if;

 if (select count(*) from pg_constraint c
     where c.conrelid='public.multigrade_assessment_items_v261'::regclass
       and c.conname='multigrade_assessment_items_v261_depth_check'
       and position('depth >= 1' in pg_get_constraintdef(c.oid))>0
       and position('depth <= 3' in pg_get_constraintdef(c.oid))>0)<>1
    or (select count(*) from pg_constraint c
        where c.conrelid='public.multigrade_adaptive_item_metadata_v262'::regclass
          and c.conname='multigrade_adaptive_item_metadata_v262_depth_check'
          and position('depth >= 1' in pg_get_constraintdef(c.oid))>0
          and position('depth <= 3' in pg_get_constraintdef(c.oid))>0)<>1 then
   raise exception 'Compat3: contrato depth 1..3 de assessment/adaptive incompatible';
 end if;

 if (select count(*) from public.deep_learning_paths_v250 where course_id='cl-8-basico' and content_version='v27.5' and status='staging')<>34
   or (select count(*) from public.curriculum_nodes_v254 where course_id='cl-8-basico' and is_active)<>136
   or (select count(*) from public.multigrade_assessment_items_v261 where course_id='cl-8-basico')<>884
   or exists(select 1 from public.deep_learning_paths_v250 where course_id='cl-8-basico' and status='published')
   or exists(select 1 from public.multigrade_assessment_items_v261 where course_id='cl-8-basico' and is_published)
   or coalesce((select live_student_delivery from public.multigrade_course_runtime_gate_v269 where course_id='cl-8-basico'),true) then
  raise exception 'Baseline cl-8-basico alterado antes de instalar 7B';
end if;

 if (select count(*) from public.deep_learning_paths_v250 where course_id='cl-1-medio' and content_version='v27.0' and status='staging')<>30
    or (select count(*) from public.multigrade_assessment_items_v261 where course_id='cl-1-medio')<>780
    or (select count(*) from public.deep_learning_paths_v250 where course_id='cl-2-medio' and content_version='v26.5' and status='staging')<>24
    or (select count(*) from public.multigrade_assessment_items_v261 where course_id='cl-2-medio')<>624
    or (select count(*) from public.deep_learning_paths_v250 where course_id='cl-3-medio' and content_version='v26.0' and status='staging')<>24
    or (select count(*) from public.multigrade_assessment_items_v261 where course_id='cl-3-medio')<>624
    or (select count(*) from public.deep_learning_paths_v250 where course_id='cl-4-medio' and status='staging')<>24
    or (select count(*) from public.school_practice_items where code like '4M-V225-P-%' and is_published)<>480
    or (select count(*) from public.school_diagnostic_items where diagnostic_version='4m-fg-v225' and is_published)<>72
    or (select count(*) from public.school_review_items where code like '4M-V225-R-%' and is_published)<>72
    or (select count(*) from public.school_review_sets where id like '4m-fg-v225-%' and is_published)<>4
    or (select count(*) from public.content_releases_v240 where release_key='4m-v240' and status='applied')<>1 then
   raise exception 'Baseline 1M-4M/V24 alterado antes de instalar 7B';
 end if;
end $$;

-- v28.0 · curriculum and deep authoring --------------------------------
insert into public.multigrade_curriculum_source_snapshot_v269(
 course_id,snapshot_date,curriculum_basis,course_url,program_url,update_process_url,
 update_process_status,requires_revalidation_before_release
) values('cl-7-basico','2026-08-12','Currículo oficial de Matemática 7.º básico actualmente publicado',
 'https://www.curriculumnacional.cl/curriculum/7o-basico-2o-medio/matematica/7-basico','https://www.curriculumnacional.cl/recursos/programa-estudio-matematica-7-basico','https://www.curriculumnacional.cl/actualizacion-curricular','monitoring',true)
on conflict(course_id) do update set snapshot_date=excluded.snapshot_date,curriculum_basis=excluded.curriculum_basis,
 course_url=excluded.course_url,program_url=excluded.program_url,update_process_url=excluded.update_process_url,
 update_process_status='monitoring',requires_revalidation_before_release=true,revalidated_at=null,revalidated_by=null,
 revalidation_notes=null,updated_at=now();

insert into public.multigrade_course_runtime_gate_v269(
 course_id,content_version,assessment_version,adaptive_calibration_status,human_content_review_required,
 human_assessment_review_required,live_student_delivery,release_candidate,blocker_codes
) values('cl-7-basico','v28.0','v28.1','heuristic_candidate',true,true,false,false,
 '["CURRICULUM_REVALIDATION_REQUIRED_BEFORE_RELEASE","HUMAN_CONTENT_REVIEW_PENDING","HUMAN_ASSESSMENT_CERTIFICATION_PENDING","ADAPTIVE_CALIBRATION_PENDING","LIVE_STUDENT_DELIVERY_DISABLED"]'::jsonb)
on conflict(course_id) do update set content_version='v28.0',assessment_version='v28.1',adaptive_calibration_status='heuristic_candidate',
 human_content_review_required=true,human_assessment_review_required=true,live_student_delivery=false,release_candidate=false,
 blocker_codes=excluded.blocker_codes,updated_at=now();

insert into public.curriculum_sources_v254(source_key,course_id,kind,title,url,authority,notes)
select source_key,course_id,kind,title,url,authority,notes
from jsonb_to_recordset($sources$[{"source_key":"mineduc-7b-course","course_id":"cl-7-basico","kind":"official_curriculum_page","title":"Matemática 7.º básico","url":"https://www.curriculumnacional.cl/curriculum/7o-basico-2o-medio/matematica/7-basico","authority":"UCE Mineduc","notes":"Currículo oficial actualmente publicado."},{"source_key":"mineduc-7b-program","course_id":"cl-7-basico","kind":"official_program","title":"Programa de Estudio Matemática 7.º básico","url":"https://www.curriculumnacional.cl/recursos/programa-estudio-matematica-7-basico","authority":"UCE Mineduc","notes":"Programa oficial consultado para la organización del nivel."},{"source_key":"mineduc-7b-update-1b-2m","course_id":"cl-7-basico","kind":"official_update_process","title":"Actualización Curricular 1.º básico a 2.º medio","url":"https://www.curriculumnacional.cl/actualizacion-curricular","authority":"Mineduc","notes":"Proceso en seguimiento; requiere revalidación antes de release."},{"source_key":"mineduc-7b-oa-01","course_id":"cl-7-basico","kind":"official_oa","title":"MA07 OA 01","url":"https://www.curriculumnacional.cl/curriculum/7o-basico-2o-medio/matematica/7-basico/ma07-oa-01","authority":"UCE Mineduc","notes":"Mostrar que comprenden la adición y la sustracción de números enteros: representando los números enteros en la recta numérica; representándolas de manera concreta, pictórica y simbólica; dándole significado a los símbolos + y − según el contexto; resolviendo problemas en contextos cotidianos.","source_sha256":"1a2e1a434afb45207dcf60cf086ddd0b19feb7289a29f46f14fb0e0d43c1e807","source_status":"normalized_official_statement"},{"source_key":"mineduc-7b-oa-02","course_id":"cl-7-basico","kind":"official_oa","title":"MA07 OA 02","url":"https://www.curriculumnacional.cl/curriculum/7o-basico-2o-medio/matematica/7-basico/ma07-oa-02","authority":"UCE Mineduc","notes":"Explicar la multiplicación y la división de fracciones positivas: utilizando representaciones concretas, pictóricas y simbólicas; relacionándolas con la multiplicación y la división de números decimales.","source_sha256":"f172d19929b3b0c4f3085d5e0c2b092ac4b4f18d3c59ae14fa8ea52b285d933a","source_status":"normalized_official_statement"},{"source_key":"mineduc-7b-oa-03","course_id":"cl-7-basico","kind":"official_oa","title":"MA07 OA 03","url":"https://www.curriculumnacional.cl/curriculum/7o-basico-2o-medio/matematica/7-basico/ma07-oa-03","authority":"UCE Mineduc","notes":"Resolver problemas que involucren la multiplicación y la división de fracciones y de decimales positivos de manera concreta, pictórica y simbólica, de forma manual y/o con software educativo.","source_sha256":"b7a8980b2f760ea8a0727fee64d61584c0441b92a725b9e4596f664a896484c2","source_status":"normalized_official_statement"},{"source_key":"mineduc-7b-oa-04","course_id":"cl-7-basico","kind":"official_oa","title":"MA07 OA 04","url":"https://www.curriculumnacional.cl/curriculum/7o-basico-2o-medio/matematica/7-basico/ma07-oa-04","authority":"UCE Mineduc","notes":"Mostrar que comprenden el concepto de porcentaje: representándolo de manera pictórica; calculando de varias maneras; aplicándolo a situaciones sencillas.","source_sha256":"6ef703ac815536d7851dbd84598fb3729ce0dc76acf4e8c131c78f9b7fc9f4b7","source_status":"normalized_official_statement"},{"source_key":"mineduc-7b-oa-05","course_id":"cl-7-basico","kind":"official_oa","title":"MA07 OA 05","url":"https://www.curriculumnacional.cl/curriculum/7o-basico-2o-medio/matematica/7-basico/ma07-oa-05","authority":"UCE Mineduc","notes":"Utilizar potencias de base 10 con exponente natural: usando los términos potencia, base, exponente y elevado; definiendo y usando el exponente 0 en el sistema decimal; expresando números naturales en notación científica; resolviendo problemas, usando la notación científica.","source_sha256":"76206392c5b8ad23ef89b691e4a9ac90c58cc632c490e1e230178cd76f4e4092","source_status":"normalized_official_statement"},{"source_key":"mineduc-7b-oa-06","course_id":"cl-7-basico","kind":"official_oa","title":"MA07 OA 06","url":"https://www.curriculumnacional.cl/curriculum/7o-basico-2o-medio/matematica/7-basico/ma07-oa-06","authority":"UCE Mineduc","notes":"Utilizar el lenguaje algebraico para generalizar relaciones entre números, para establecer y formular reglas y propiedades y construir ecuaciones.","source_sha256":"b8b17499de75cc4c0a5931c89ebf476b531e8ca4ec0f664d18af891d1b927e17","source_status":"normalized_official_statement"},{"source_key":"mineduc-7b-oa-07","course_id":"cl-7-basico","kind":"official_oa","title":"MA07 OA 07","url":"https://www.curriculumnacional.cl/curriculum/7o-basico-2o-medio/matematica/7-basico/ma07-oa-07","authority":"UCE Mineduc","notes":"Reducir expresiones algebraicas, reuniendo términos semejantes para obtener expresiones de la forma ax + by + cz, con a, b, c pertenecientes a los números enteros.","source_sha256":"335aac454187b326ca5391e4390adc69b9ef990cff35ae05019ebb4ea6e0f845","source_status":"normalized_official_statement"},{"source_key":"mineduc-7b-oa-08","course_id":"cl-7-basico","kind":"official_oa","title":"MA07 OA 08","url":"https://www.curriculumnacional.cl/curriculum/7o-basico-2o-medio/matematica/7-basico/ma07-oa-08","authority":"UCE Mineduc","notes":"Mostrar que comprenden las proporciones directas e inversas: realizando tablas de valores para relaciones proporcionales; graficando los valores de la tabla; explicando las características de la gráfica; resolviendo problemas de la vida diaria y de otras asignaturas.","source_sha256":"fbfac4508d283e1a23e6c415706066ead24377de5e58dbc95375c00a1dfb7a71","source_status":"normalized_official_statement"},{"source_key":"mineduc-7b-oa-09","course_id":"cl-7-basico","kind":"official_oa","title":"MA07 OA 09","url":"https://www.curriculumnacional.cl/curriculum/7o-basico-2o-medio/matematica/7-basico/ma07-oa-09","authority":"UCE Mineduc","notes":"Modelar y resolver problemas diversos de la vida diaria y de otras asignaturas, que involucran ecuaciones e inecuaciones lineales de las formas ax=b, x/a=b, ax<b, ax>b, x/a<b y x/a>b, con a y b enteros y a distinto de cero.","source_sha256":"8768d743df944e2962bdbec79efa48d9dd5dcd82fa28c9f3877ab937ff3bae54","source_status":"normalized_official_statement"},{"source_key":"mineduc-7b-oa-10","course_id":"cl-7-basico","kind":"official_oa","title":"MA07 OA 10","url":"https://www.curriculumnacional.cl/curriculum/7o-basico-2o-medio/matematica/7-basico/ma07-oa-10","authority":"UCE Mineduc","notes":"Descubrir relaciones que involucran ángulos exteriores o interiores de diferentes polígonos.","source_sha256":"84ff1bc7c977e5d98c087edb477348b8993ffba58eb14d7055cd2abde82a785b","source_status":"normalized_official_statement"},{"source_key":"mineduc-7b-oa-11","course_id":"cl-7-basico","kind":"official_oa","title":"MA07 OA 11","url":"https://www.curriculumnacional.cl/curriculum/7o-basico-2o-medio/matematica/7-basico/ma07-oa-11","authority":"UCE Mineduc","notes":"Mostrar que comprenden el círculo: describiendo las relaciones entre el radio, el diámetro y el perímetro del círculo; estimando de manera intuitiva el perímetro y el área de un círculo; aplicando las aproximaciones del perímetro y del área en la resolución de problemas geométricos, de otras asignaturas y de la vida diaria; identificándolo como lugar geométrico.","source_sha256":"1dcc4f300f5c431696f5fbd412a10a000dd30abca6b72c7a67f716e428874ac0","source_status":"normalized_official_statement"},{"source_key":"mineduc-7b-oa-12","course_id":"cl-7-basico","kind":"official_oa","title":"MA07 OA 12","url":"https://www.curriculumnacional.cl/curriculum/7o-basico-2o-medio/matematica/7-basico/ma07-oa-12","authority":"UCE Mineduc","notes":"Construir objetos geométricos de manera manual y/o con software educativo: líneas, como las perpendiculares, paralelas, bisectrices y alturas en triángulos y cuadriláteros; puntos, como el punto medio, centro de gravedad, centro del círculo inscrito y circunscrito de un triángulo; triángulos y cuadriláteros congruentes.","source_sha256":"36d0879c870fb1e04dd7edefc4a12c535150f9eb2e8faa1ac9c7427068b97676","source_status":"normalized_official_statement"},{"source_key":"mineduc-7b-oa-13","course_id":"cl-7-basico","kind":"official_oa","title":"MA07 OA 13","url":"https://www.curriculumnacional.cl/curriculum/7o-basico-2o-medio/matematica/7-basico/ma07-oa-13","authority":"UCE Mineduc","notes":"Desarrollar y aplicar la fórmula del área de triángulos, paralelógramos y trapecios.","source_sha256":"c66f4ba98d5f032a026977e345ee905a13e703f10da9e6adf2006b9e275a241f","source_status":"normalized_official_statement"},{"source_key":"mineduc-7b-oa-14","course_id":"cl-7-basico","kind":"official_oa","title":"MA07 OA 14","url":"https://www.curriculumnacional.cl/curriculum/7o-basico-2o-medio/matematica/7-basico/ma07-oa-14","authority":"UCE Mineduc","notes":"Identificar puntos en el plano cartesiano, usando pares ordenados y vectores de forma concreta, mediante juegos, y pictórica.","source_sha256":"fe088e970629a5fc4a0e228a07469c5b4f39920a22fd5519ee33ac6ba8c1a809","source_status":"normalized_official_statement"},{"source_key":"mineduc-7b-oa-15","course_id":"cl-7-basico","kind":"official_oa","title":"MA07 OA 15","url":"https://www.curriculumnacional.cl/curriculum/7o-basico-2o-medio/matematica/7-basico/ma07-oa-15","authority":"UCE Mineduc","notes":"Estimar el porcentaje de algunas características de una población desconocida por medio del muestreo.","source_sha256":"7366e1430e8fbe72f0e9910504693249424b732c535d3d8515a5aebb09a19310","source_status":"normalized_official_statement"},{"source_key":"mineduc-7b-oa-16","course_id":"cl-7-basico","kind":"official_oa","title":"MA07 OA 16","url":"https://www.curriculumnacional.cl/curriculum/7o-basico-2o-medio/matematica/7-basico/ma07-oa-16","authority":"UCE Mineduc","notes":"Representar datos obtenidos en una muestra mediante tablas de frecuencias absolutas y relativas, utilizando gráficos apropiados, de manera manual y/o con software educativo.","source_sha256":"937687d15feab483bee1d49314f8089e4bc0473d79ad665663141421c0bf4816","source_status":"normalized_official_statement"},{"source_key":"mineduc-7b-oa-17","course_id":"cl-7-basico","kind":"official_oa","title":"MA07 OA 17","url":"https://www.curriculumnacional.cl/curriculum/7o-basico-2o-medio/matematica/7-basico/ma07-oa-17","authority":"UCE Mineduc","notes":"Mostrar que comprenden las medidas de tendencia central y el rango: determinando las medidas de tendencia central para realizar inferencias sobre la población; determinando la medida de tendencia central adecuada para responder un problema planteado; utilizándolos para comparar dos poblaciones; determinando el efecto de un dato que es muy diferente a los otros.","source_sha256":"2dd29b4ffa6a4156071cef50b6c091ec4360007a1a39b2c543a674b275436f77","source_status":"normalized_official_statement"},{"source_key":"mineduc-7b-oa-18","course_id":"cl-7-basico","kind":"official_oa","title":"MA07 OA 18","url":"https://www.curriculumnacional.cl/curriculum/7o-basico-2o-medio/matematica/7-basico/ma07-oa-18","authority":"UCE Mineduc","notes":"Explicar las probabilidades de eventos obtenidos por medio de experimentos de manera manual y/o con software educativo: estimándolas de manera intuitiva; utilizando frecuencias relativas; relacionándolas con razones, fracciones o porcentaje.","source_sha256":"681341cc43a93318d2bf18d81114015cb129656f3b87c01d88cc1af21ba8a568","source_status":"normalized_official_statement"},{"source_key":"mineduc-7b-oa-19","course_id":"cl-7-basico","kind":"official_oa","title":"MA07 OA 19","url":"https://www.curriculumnacional.cl/curriculum/7o-basico-2o-medio/matematica/7-basico/ma07-oa-19","authority":"UCE Mineduc","notes":"Comparar las frecuencias relativas de un evento obtenidas al repetir un experimento de forma manual y/o con software educativo, con la probabilidad obtenida de manera teórica, usando diagramas de árbol, tablas o gráficos.","source_sha256":"71f4e0fb7f5921c49b9c6922cf652fbbdc8a78c4f705b9d7583c52f6c537da2d","source_status":"normalized_official_statement"},{"source_key":"mineduc-7b-u1","course_id":"cl-7-basico","kind":"official_program_unit","title":"U1: Números enteros, fracciones, porcentajes y potencias.","url":"https://www.curriculumnacional.cl/recursos/programa-estudio-matematica-7-basico","authority":"UCE Mineduc","notes":"Unidad de organización del macrobloque basada en el programa oficial."},{"source_key":"mineduc-7b-u2","course_id":"cl-7-basico","kind":"official_program_unit","title":"U2: Lenguaje algebraico, proporcionalidad, ecuaciones e inecuaciones.","url":"https://www.curriculumnacional.cl/recursos/programa-estudio-matematica-7-basico","authority":"UCE Mineduc","notes":"Unidad de organización del macrobloque basada en el programa oficial."},{"source_key":"mineduc-7b-u3","course_id":"cl-7-basico","kind":"official_program_unit","title":"U3: Ángulos, círculo, construcciones, áreas y plano cartesiano.","url":"https://www.curriculumnacional.cl/recursos/programa-estudio-matematica-7-basico","authority":"UCE Mineduc","notes":"Unidad de organización del macrobloque basada en el programa oficial."},{"source_key":"mineduc-7b-u4","course_id":"cl-7-basico","kind":"official_program_unit","title":"U4: Muestreo, frecuencias, tendencia central y probabilidad.","url":"https://www.curriculumnacional.cl/recursos/programa-estudio-matematica-7-basico","authority":"UCE Mineduc","notes":"Unidad de organización del macrobloque basada en el programa oficial."}]$sources$::jsonb)
